    STRUCT('E187' AS event_id, 'Maharashtra' AS state, '2024-0647-IND' AS source_record_id, DATE '2024-08-26' AS onset_date, DATE '2024-08-26' AS query_start, DATE '2024-11-27' AS query_end, ['maharashtra'] AS location_terms),
