    STRUCT('E201' AS event_id, 'Punjab' AS state, '2025-0751-IND' AS source_record_id, DATE '2025-08-15' AS onset_date, DATE '2025-08-15' AS query_start, DATE '2025-11-16' AS query_end, ['punjab'] AS location_terms),
