    STRUCT('E203' AS event_id, 'Bihar' AS state, '2025-0859-IND' AS source_record_id, DATE '2025-10-03' AS onset_date, DATE '2025-10-03' AS query_start, DATE '2026-01-04' AS query_end, ['bihar'] AS location_terms),
    STRUCT('E204' AS event_id, 'West Bengal' AS state, '2025-0859-IND' AS source_record_id, DATE '2025-10-03' AS onset_date, DATE '2025-10-03' AS query_start, DATE '2026-01-04' AS query_end, ['west bengal'] AS location_terms)
  ])
),
gkg_raw AS (
  SELECT
    PARSE_TIMESTAMP('%Y%m%d%H%M%S', CAST(`DATE` AS STRING), 'UTC') AS published_at,
    DocumentIdentifier AS url,
    TRIM(DocumentIdentifier) AS normalized_url,
    LOWER(COALESCE(V2Locations, '')) AS locations_lower,
    CAST('' AS STRING) AS title_lower,
    CASE
      WHEN REGEXP_EXTRACT(COALESCE(TranslationInfo, ''), r'srclc:([a-z]{3})') = 'eng' THEN 'en'
      ELSE COALESCE(
        REGEXP_EXTRACT(COALESCE(TranslationInfo, ''), r'srclc:([a-z]{3})'),
        'en'
      )
    END AS source_lang,
    CAST(NULL AS STRING) AS gkg_record_id,
    LOWER(COALESCE(NET.REG_DOMAIN(DocumentIdentifier), '')) AS source_domain,
    CAST(NULL AS STRING) AS title,
    CAST(NULL AS STRING) AS authors,
    CAST(NULL AS FLOAT64) AS tone,
    CAST(NULL AS STRING) AS sharing_image
  FROM `gdelt-bq.gdeltv2.gkg_partitioned`
  WHERE (
        (_PARTITIONTIME >= TIMESTAMP('2019-07-14') AND _PARTITIONTIME < TIMESTAMP('2020-03-02'))
        OR (_PARTITIONTIME >= TIMESTAMP('2020-05-10') AND _PARTITIONTIME < TIMESTAMP('2020-09-03'))
        OR (_PARTITIONTIME >= TIMESTAMP('2020-10-01') AND _PARTITIONTIME < TIMESTAMP('2021-01-03'))
        OR (_PARTITIONTIME >= TIMESTAMP('2021-06-01') AND _PARTITIONTIME < TIMESTAMP('2022-02-20'))
        OR (_PARTITIONTIME >= TIMESTAMP('2022-05-17') AND _PARTITIONTIME < TIMESTAMP('2022-12-21'))
        OR (_PARTITIONTIME >= TIMESTAMP('2023-06-14') AND _PARTITIONTIME < TIMESTAMP('2023-10-29'))
        OR (_PARTITIONTIME >= TIMESTAMP('2023-12-18') AND _PARTITIONTIME < TIMESTAMP('2024-03-21'))
        OR (_PARTITIONTIME >= TIMESTAMP('2024-05-01') AND _PARTITIONTIME < TIMESTAMP('2025-01-06'))
        OR (_PARTITIONTIME >= TIMESTAMP('2025-05-31') AND _PARTITIONTIME < TIMESTAMP('2026-01-05'))
      )
      AND `DATE` >= 20190714000000
      AND `DATE` <= 20260104235959
      AND DocumentIdentifier IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM UNNEST(SPLIT(COALESCE(V2Locations, ''), ';')) AS location_ref
        WHERE UPPER(SPLIT(location_ref, '#')[SAFE_OFFSET(2)]) = 'IN'
      )
      AND EXISTS (
        SELECT 1
        FROM UNNEST(SPLIT(COALESCE(V2Themes, ''), ';')) AS theme_ref
        WHERE SPLIT(theme_ref, ',')[SAFE_OFFSET(0)] IN UNNEST(['NATURAL_DISASTER_FLOOD', 'NATURAL_DISASTER_FLOODING', 'NATURAL_DISASTER_FLOODS', 'NATURAL_DISASTER_FLOODED', 'NATURAL_DISASTER_FLOODED_AREAS', 'NATURAL_DISASTER_FLOODED_ROAD', 'NATURAL_DISASTER_FLOODED_ROADS', 'NATURAL_DISASTER_FLOODWATER', 'NATURAL_DISASTER_FLOODWATERS', 'NATURAL_DISASTER_FLOOD_WARNING', 'NATURAL_DISASTER_FLOOD_WATER', 'NATURAL_DISASTER_FLOOD_WATERS', 'NATURAL_DISASTER_FLASH_FLOOD', 'NATURAL_DISASTER_FLASH_FLOODS'])
      )
),
gkg AS (
  SELECT *
  FROM gkg_raw
  WHERE source_lang IN UNNEST(['en', 'ara', 'ben', 'guj', 'hin', 'kan', 'mal', 'mar', 'nep', 'ori', 'pan', 'pus', 'snd', 'tam', 'tel', 'urd'])
),
candidate_matches AS (
  SELECT
    e.event_id,
    e.state,
    e.source_record_id,
    e.onset_date,
    g.*,
    ABS(DATE_DIFF(DATE(g.published_at), e.onset_date, DAY)) AS onset_distance
  FROM event_windows e
  JOIN gkg AS g
    ON DATE(g.published_at) BETWEEN e.query_start AND e.query_end
  WHERE (
     EXISTS (
       SELECT 1
       FROM UNNEST(SPLIT(g.locations_lower, ';')) AS location_ref
       CROSS JOIN UNNEST(e.location_terms) AS term
       WHERE SPLIT(location_ref, '#')[SAFE_OFFSET(2)] = 'in'
         AND EXISTS (
           SELECT 1
           FROM UNNEST(SPLIT(
             COALESCE(SPLIT(location_ref, '#')[SAFE_OFFSET(1)], ''), ','
           )) AS location_part
           WHERE TRIM(location_part) = term
         )
     )
     OR EXISTS (
       SELECT 1
       FROM UNNEST(e.location_terms) AS term
       WHERE STRPOS(
         CONCAT(' ', REGEXP_REPLACE(g.title_lower, r'[^a-z0-9]+', ' '), ' '),
         CONCAT(' ', REGEXP_REPLACE(term, r'[^a-z0-9]+', ' '), ' ')
       ) > 0
     )
   )
),
assigned AS (
  SELECT * EXCEPT(assignment_rank, onset_distance)
  FROM (
    SELECT *, ROW_NUMBER() OVER (
      PARTITION BY normalized_url, state
      ORDER BY onset_distance, onset_date, event_id, published_at, url
    ) AS assignment_rank
    FROM candidate_matches
  )
  WHERE assignment_rank = 1
)

SELECT
  event_id,
  state,
  source_record_id,
  gkg_record_id,
  onset_date,
  published_at,
  url,
  normalized_url,
  source_domain,
  source_lang,
  title,
  authors,
  tone,
  sharing_image
FROM assigned
ORDER BY event_id, published_at, normalized_url
